const __pageData = JSON.parse('{"title":"Go++ gpp fmt Command Specification","description":"","frontmatter":{},"headers":[],"relativePath":"reference/specifications/fmt.md","filePath":"reference/specifications/fmt.md","lastUpdated":null}');
